פרד/ת בעזרת הטקס, עם קושי", "נפרד/ת בעזרת הטקס ונרגע/ת מהר", "מזכיר/ה את הטקס בעצמו/ה ונפרד/ת"]}, {"id": "t5", "text": "כשיש צורך, מבקש/ת עזרה ממבוגר במילה, בתנועה או בהצבעה", "staff": "מראה לנו או אומר/ת כשצריך עזרה", "scale": ["לא מבקש/ת עזרה, מתוסכל/ת לבד", "מבקש/ת רק בבכי או בצעקה", "מבקש/ת בתנועה כשהמבוגר שואל", "מבקש/ת בעצמו/ה בתנועה או במילה", "מבקש/ת במילים ממבוגרים שונים"]}], "interventions": [{"id": "i1", "name": "רגע חיבור קבוע", "what": "פעם במשמרת, 2–3 דקות של משחק או שיחה שהילד/ה מוביל/ה. בגובה העיניים, בשם, במילים פשוטות.", "why": "רגעים קבועים וצפויים בונים אמון שהמבוגר יהיה שם.", "freq": "פעם בכל משמרת", "approach": "TBRI", "targets": ["t1", "t3"], "sentences": ["עכשיו הזמן שלנו. מה נשחק?", "אני כאן איתך"], "avoid": "לא לבטל את רגע החיבור כעונש"}, {"id": "i2", "name": "ברכה אישית", "what": "בתחילת היום ובתחילת המשמרת מברכים בשם ובגובה העיניים, ומחכים לתגובה בלי לדרוש אותה.", "why": "הילד/ה לומד/ת שמחכים לו/ה ושמחים לראות אותו/ה.", "freq": "בכל בוקר ובכל תחילת משמרת", "approach": "מעגל הביטחון", "targets": ["t1"], "sentences": ["בוקר טוב! איזה כיף לראות אותך", "אני כאן היום עד הערב"], "avoid": "לא לדרוש תשובה, נשיקה או חיבוק"}, {"id": "i3", "name": "נוכחות רגועה כשקשה", "what": "כשהילד/ה במצוקה מתקרבים לאט, מורידים את הקול ואת הגוף, ונשארים קרוב במרחק שנוח לו/ה. לא דורשים לדבר.", "why": "ילד/ה קטן/ה נרגע/ת דרך מבוגר רגוע (ויסות משותף), לא לבד.", "freq": "בכל רגע של מצוקה", "approach": "NMT", "targets": ["t2"], "sentences": ["אני כאן. אני איתך", "קשה לך. אני לידך"], "avoid": "לא להגיד \"תירגע/י\", ולא לבודד כעונש"}, {"id": "i4", "name": "טקס פרידה קבוע", "what": "בכל פרידה ובחילופי משמרת אותו טקס קצר: אומרים מי נשאר איתו/ה ומתי נתראה, ומשאירים לו/ה משהו קטן להחזיק.", "why": "פרידה צפויה מפחיתה את הפחד מאובדן.", "freq": "בכל פרידה ובכל חילופי משמרת", "approach": "ARC", "targets": ["t4"], "sentences": ["עכשיו המשמרת מתחלפת, ומחר נתראה", "זה בשבילך לשמור עד שנתראה"], "avoid": "לא להיעלם בלי להיפרד, גם כשהילד/ה עסוק/ה"}, {"id": "i5", "name": "הכנה לפני מעבר", "what": "לפני שינוי (סוף משחק, יציאה, מקלחת, שינה) מודיעים מראש במילים ובתמונה, ובאותו משפט בכל פעם.", "why": "כשיודעים מה יקרה, מרגישים בטוחים יותר.", "freq": "לפני כל מעבר", "approach": "ARC", "targets": ["t4", "t2"], "sentences": ["עוד שיר אחד, ואז הולכים לאכול", "קודם מקלחת, ואחר כך סיפור"], "avoid": "לא להפתיע בשינויים כשאפשר להכין"}, {"id": "i6", "name": "בסיס בטוח במשחק", "what": "יושבים במקום קבוע ליד המשחק, מחייכים כשהילד/ה מסתכל/ת, ומקבלים בחום כשהוא/היא חוזר/ת.", "why": "ילד/ה שיודע/ת שיש לאן לחזור, מעז/ה לצאת ולחקור.", "freq": "בזמני משחק", "approach": "מעגל הביטחון", "targets": ["t3"], "sentences": ["אני פה. אפשר ללכת לשחק", "חזרת! ספר/י לי מה עשית"], "avoid": "לא לצאת מהחדר בלי להגיד"}, {"id": "i7", "name": "עונים לבקשת עזרה", "what": "כשהילד/ה מבקש/ת עזרה בכל דרך, עונים מהר, אומרים במילים מה הבנו, ומראים איך מבקשים בפעם הבאה.", "why": "כל בקשה שנענית מלמדת שכדאי לפנות למבוגר.", "freq": "בכל פעם שמבקש/ת", "approach": "TBRI", "targets": ["t5"], "sentences": ["ביקשת עזרה, איזה יופי. בוא/י נעשה את זה יחד", "אפשר להגיד: עזרה"], "avoid": "לא להתעלם מבקשה שנאמרה בבכי או בצעקה"}, {"id": "i8", "name": "משחק קצר ושמח", "what": "5 דקות של משחק מוכר שהמבוגר מוביל, למשל מחיאות כפיים בקצב או מחבואים קטנים, עם מבט וחיוך. רק אם הילד/ה רוצה.", "why": "משחק משותף ושמח בונה קשר ותחושת ביטחון.", "freq": "פעם ביום", "approach": "Theraplay", "targets": ["t1", "t3"], "sentences": ["בוא/י נשחק את המשחק שלנו", "איפה הידיים? הנה הן!"], "avoid": "לא לכפות מגע או מבט בעיניים"}]}}}'::jsonb, true) on conflict (scope, institution, kind, title) do update set description = excluded.description, themes = excluded.themes, category = excluded.category, methods = excluded.methods, content = excluded.content, active = true where mercury_library.draft;

